package vidazoo

import (
	"encoding/json"
	"fmt"
	"net/http"
	"net/url"
	"strconv"
	"strings"

	"github.com/prebid/openrtb/v20/openrtb2"
	"github.com/prebid/prebid-server/v3/adapters"
	"github.com/prebid/prebid-server/v3/config"
	"github.com/prebid/prebid-server/v3/errortypes"
	"github.com/prebid/prebid-server/v3/openrtb_ext"
	"github.com/prebid/prebid-server/v3/util/jsonutil"
)

type adapter struct {
	endpoint string
}

// Builder builds a new instance of the Vidazoo for the given bidder with the given config.
func Builder(bidderName openrtb_ext.BidderName, config config.Adapter, server config.Server) (adapters.Bidder, error) {
	bidder := &adapter{
		endpoint: config.Endpoint,
	}
	return bidder, nil
}

func (a *adapter) MakeRequests(request *openrtb2.BidRequest, requestInfo *adapters.ExtraRequestInfo) ([]*adapters.RequestData, []error) {
	var requests []*adapters.RequestData
	var errors []error

	requestCopy := *request

	for _, imp := range request.Imp {
		requestCopy.Imp = []openrtb2.Imp{imp}

		// NewsBreak Custom Prebid Code Starts
		tagId, err := extractTagId(&imp)
		if err != nil {
			errors = append(errors, fmt.Errorf("extract tagId: %w", err))
			continue
		}
		for i := range requestCopy.Imp {
			requestCopy.Imp[i].TagID = tagId
		}
		// NewsBreak Custom Prebid Code Ends

		requestJSON, err := json.Marshal(&requestCopy)
		if err != nil {
			errors = append(errors, fmt.Errorf("marshal bidRequest: %w", err))
			continue
		}

		cId, err := extractCid(&imp)
		if err != nil {
			errors = append(errors, fmt.Errorf("extract cId: %w", err))
			continue
		}

		headers := http.Header{}
		headers.Add("Content-Type", "application/json;charset=utf-8")

		requestData := &adapters.RequestData{
			Method:  "POST",
			Uri:     fmt.Sprintf("%s%s", a.endpoint, url.QueryEscape(cId)),
			Body:    requestJSON,
			Headers: headers,
			ImpIDs:  []string{imp.ID},
		}

		requests = append(requests, requestData)
	}

	return requests, errors
}

func getMediaTypeForBid(bid openrtb2.Bid) (openrtb_ext.BidType, error) {
	switch bid.MType {
	case openrtb2.MarkupBanner:
		return openrtb_ext.BidTypeBanner, nil
	case openrtb2.MarkupVideo:
		return openrtb_ext.BidTypeVideo, nil
	}
	return "", &errortypes.BadInput{
		Message: fmt.Sprintf("Could not define bid type for imp: %s", bid.ImpID),
	}
}

